True import random
def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] + [0]*w for row in grid] + [[0]*(2*w) for _ in range(h)]
    vals = [v for row in grid for v in row] * 4
    for row in grid:
        for v in row: vals.remove(v)
    random.Random(5).shuffle(vals)
    k=0
    for r in range(2*h):
        for c in range(2*w):
            if r < h and c < w: continue
            out[r][c]=vals[k]; k+=1
    return out

